import{g as a,ad as e,r as n,A as p}from"./chunks/framework.BT7BGxmb.js";const h=JSON.parse('{"title":"useDoc","description":"","frontmatter":{},"headers":[],"relativePath":"docs/data-fetching/use-doc.md","filePath":"docs/data-fetching/use-doc.md","lastUpdated":1786211690000}'),c={name:"docs/data-fetching/use-doc.md"};function l(o,s,t,d,i,r){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="usedoc" tabindex="-1">useDoc <a class="header-anchor" href="#usedoc" aria-label="Permalink to “useDoc”">​</a></h1><p><code>useDoc</code> fetches a single Frappe document and keeps it reactive. Documents are shared across every <code>useDoc</code> call for the same <code>doctype</code>/<code>name</code> — two components rendering the same document read the same cached copy and update together.</p><h2 id="basic-example" tabindex="-1">Basic example <a class="header-anchor" href="#basic-example" aria-label="Permalink to “Basic example”">​</a></h2><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> v-if</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.doc</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">    {{ todo.doc.description }}</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.setValue.submit({ status: &#39;Closed&#39; })</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx"> Close </span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useDoc</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useDoc</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="reactive-name" tabindex="-1">Reactive name <a class="header-anchor" href="#reactive-name" aria-label="Permalink to “Reactive name”">​</a></h2><p><code>name</code> accepts a <code>Ref</code> or a getter, so <code>useDoc</code> can follow a document that changes — e.g. a <code>name</code> coming from the route:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useRoute</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue-router</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useDoc</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> route</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useRoute</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useDoc</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  name</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_22m8k2"> route</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">params</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>The request refires automatically whenever <code>name</code> resolves to a new value.</p><h2 id="document-methods" tabindex="-1">Document methods <a class="header-anchor" href="#document-methods" aria-label="Permalink to “Document methods”">​</a></h2><p><code>methods</code> exposes whitelisted document methods (<code>doc.run_method(...)</code> on the server) as their own <code>useCall</code>-shaped members:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useDoc</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useDoc</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  methods</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_1th9sy">    // shorthand: the server method name</span></span>
<span class="line"><span class="s_r4oegk">    markDone</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">mark_done</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1th9sy">    // full options, same shape as useCall (minus url/method/immediate)</span></span>
<span class="line"><span class="s_r4oegk">    reassign</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_12xt1b">      name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">reassign</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">      onSuccess</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_22m8k2"> console</span><span class="s_1jjt6x">.</span><span class="s_indoxt">log</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">reassigned</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">    }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">todo</span><span class="s_1jjt6x">.</span><span class="s_11933w">markDone</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_22m8k2">todo</span><span class="s_1jjt6x">.</span><span class="s_11933w">reassign</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> allocated_to</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">jane@example.com</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><ul><li><code>doctype</code> — the DocType of the document.</li><li><code>name</code> — the document&#39;s name. Accepts a plain string, a <code>Ref&lt;string&gt;</code> or a getter for a reactively-changing document.</li><li><code>baseUrl</code> — prefix prepended to the generated request URLs.</li><li><code>url</code> — overrides the default <code>/api/v2/document/&lt;doctype&gt;/&lt;name&gt;</code> GET URL.</li><li><code>methods</code> — a map of member name to either a server method name (string), or a <a href="./use-call"><code>useCall</code></a> options object (minus <code>url</code> and <code>baseUrl</code>) plus a required <code>name</code> naming the server method. Defaults to <code>method: &#39;POST&#39;</code> and <code>immediate: false</code>; both can be overridden per method. Each becomes a <code>useCall</code>-shaped member on the returned object.</li><li><code>immediate</code> — fire the initial GET automatically once <code>name</code> resolves. Defaults to <code>true</code>.</li><li><code>staleOnError</code> — when <code>true</code>, a failed refetch keeps showing the last known <code>doc</code> instead of clearing it. Defaults to <code>false</code>.</li><li><code>transform</code> — receives the fetched document (with <code>doctype</code> set) and returns the value <code>doc</code> should hold.</li></ul><h2 id="return-value" tabindex="-1">Return value <a class="header-anchor" href="#return-value" aria-label="Permalink to “Return value”">​</a></h2><ul><li><code>doc</code> — the document, or <code>null</code> before it has been fetched.</li><li><code>error</code> — the error from the last fetch, or <code>null</code>.</li><li><code>loading</code> (alias <code>isFetching</code>) — <code>true</code> while the document is being fetched.</li><li><code>isFinished</code> — <code>true</code> once the current fetch has settled, either way.</li><li><code>canAbort</code> — <code>true</code> while a fetch that can still be aborted is in flight.</li><li><code>aborted</code> — <code>true</code> if the last fetch was aborted.</li><li><code>execute()</code> (aliases <code>fetch()</code>, <code>reload()</code>) — refetches the document. Returns a promise that resolves with the response, or rejects if the fetch fails.</li><li><code>abort()</code> — aborts the in-flight fetch.</li><li><code>setValue</code> — a <a href="./use-call"><code>useCall</code></a>-shaped member; <code>setValue.submit(values)</code> <code>PUT</code>s a partial update and writes the response back into <code>doc</code>.</li><li><code>delete</code> — a <code>useCall</code>-shaped member; <code>delete.submit()</code> deletes the document and clears it from every <code>useDoc</code>/<code>useList</code> reading it.</li><li><code>onSuccess(callback)</code> — registers a callback that runs with the document every time <em>this</em> <code>useDoc</code> call&#39;s own fetch (the initial load, or a <code>reload()</code>) succeeds. Returns an unsubscribe function.</li><li>one member per entry in <code>methods</code>, each a <code>useCall</code>-shaped object.</li></ul><h2 id="shared-cache" tabindex="-1">Shared cache <a class="header-anchor" href="#shared-cache" aria-label="Permalink to “Shared cache”">​</a></h2><p>Every <code>useDoc</code> (and matching row in a <a href="./use-list"><code>useList</code></a>) for the same <code>doctype</code>/<code>name</code> reads from one shared, reactive store. Calling <code>setValue</code> or <code>delete</code> from any of them updates <code>doc</code> everywhere that document is being read, and a document written by <code>useNewDoc</code> is immediately readable through <code>useDoc</code> under its returned <code>name</code>.</p>`,17)])])}const u=a(c,[["render",l]]);export{h as __pageData,u as default};
